pm.test("HTTP 201", function () { pm.response.to.have.status(201); });
const body = pm.response.json();
pm.test('Returns the created account DTO', function () {
  pm.expect(body).to.have.property('account').that.is.an('object');
  pm.expect(body.account._id).to.match(/^[a-f0-9]{24}$/i);
  pm.expect(body.account.providerName).to.eql("nitter");
  pm.expect(body.account.platform).to.eql('x');
  pm.expect(body.account.enabled).to.eql(true);
  pm.expect(body.account.monitoringStatus).to.eql('active');
  pm.expect(body.account.notificationBaselineAt).to.be.undefined;
});

